async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  let lineNumber = 0;
  let delivered = 0;
  let pending = "";

  const processLine = async (rawLine) => {
    lineNumber++;

    const line =
      rawLine.endsWith("\r") ? rawLine.slice(0, -1) : rawLine;

    if (line.trim() === "") {
      return true;
    }

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      const error = new Error(`Invalid JSON on line ${lineNumber}`);
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }

    const result = await deliver(value, lineNumber);
    delivered++;

    return result !== false;
  };

  const processText = async (text) => {
    let start = 0;

    while (true) {
      const newline = text.indexOf("\n", start);

      if (newline === -1) {
        pending += text.slice(start);
        return true;
      }

      pending += text.slice(start, newline);
      const currentLine = pending;
      pending = "";

      if (!(await processLine(currentLine))) {
        return false;
      }

      start = newline + 1;
    }
  };

  try {
    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        break;
      }

      if (!(await processText(decoder.decode(chunk, { stream: true })))) {
        return delivered;
      }
    }

    if (!(await processText(decoder.decode()))) {
      return delivered;
    }

    if (pending.length > 0) {
      await processLine(pending);
    }

    return delivered;
  } finally {
    await input.close();
  }
}
